window.BloomHelpData.register({"schema":1,"locale":"ru","nativeReviewRequired":true,"common":{"review":"Черновой перевод. Требуется проверка носителем языка.","fallback":"Часть справки показана на английском языке.","recovery":"Если возникла проблема","availability":"Кандидат для интеграции; проверьте поддержку в утверждённой сборке."},"routes":{"start":{"title":"Новая вкладка / начальная страница","summary":"Выберите вселенную, открывайте приложения или сайты и меняйте расположение панелей стартовой страницы.","step":"Откройте «Расставить». Перетащите маркер одной панели на другой или выберите два маркера, чтобы поменять панели местами. При необходимости используйте «Отменить действие» или «Сбросить расположение».","recovery":"Расположения сохраняются на этом устройстве отдельно для каждой вселенной. Если хранилище недоступно, изменения действуют только во время этого посещения."},"passwords":{"title":"Менеджер паролей (прототип интерфейса; хранилище нативное)","summary":"Осторожно используйте сохранённые данные входа.","step":"Проверьте адрес сайта перед выбором сохранённой учётной записи.","recovery":"Если хранилище заблокировано, разблокируйте его поддерживаемым способом. Никогда не включайте пароли в обращение в службу поддержки."},"settings":{"title":"Настройки","summary":"Настройте параметры просмотра.","step":"Меняйте по одному параметру и проверяйте результат.","recovery":"Оставляйте экспериментальные настройки JIT и GPU выключенными, если не следуете утверждённому плану тестирования."},"https-only":{"title":"Режим только HTTPS"},"private":{"title":"Приватный просмотр"},"themes":{"title":"Общие темы","summary":"Выберите оформление набора приложений.","step":"Посмотрите предварительный вид доступной темы и подтвердите выбор.","recovery":"Некоторым приложениям может потребоваться доработка интеграции, прежде чем они начнут следовать общей настройке."},"reader":{"title":"Режим чтения","summary":"Читайте статью с меньшим количеством отвлекающих элементов.","step":"Откройте режим чтения для текущей статьи и настройте доступные параметры текста.","recovery":"Не все страницы удаётся извлечь; вернитесь к исходной странице, если часть содержимого отсутствует."},"media":{"title":"Медиацентр"},"downloads":{"title":"Панель загрузок","summary":"Отслеживайте загрузки и управляйте ими.","step":"Проверьте состояние и папку назначения каждого задания; открывайте файлы только после завершения загрузки.","recovery":"Если задание завершилось ошибкой, сохраните её сообщение. JDownloader необязателен и должен пройти проверки Setup."},"notes":{"title":"Заметки"},"device-login":{"title":"Войдите на другом устройстве"},"status":{"title":"Состояние Bloom Core","summary":"Проверьте, какие приложения набора отвечают.","step":"Прочитайте состояние каждого приложения перед его открытием.","recovery":"Если Bloom Core не запущен, общее обнаружение приложений может быть недоступно; сохраните показанную ошибку."},"library":{"title":"Закладки и история","summary":"Найдите сохранённые ссылки и историю просмотра.","step":"Выберите «Закладки» или «История» и проверьте адрес перед открытием результата.","recovery":"Удаление локальной записи не удаляет учётную запись на сайте или её данные."},"translate":{"title":"Перевести страницу","summary":"Читайте страницу на английском языке.","step":"Проверьте адрес сайта и уведомление о Google Translate. Продолжайте только при согласии отправить адрес страницы.","recovery":"Если страница изменилась, снова откройте эту панель и подтвердите новую страницу. Перевод может быть неточным; не отправляйте конфиденциальные материалы."},"accessibility":{"title":"Специальные возможности","summary":"Сделайте интерфейс удобнее для чтения и управления.","step":"Попробуйте настройки текста, контраста и движения, доступные в этой версии.","recovery":"Если текст обрезается, запишите страницу, язык и разрешение экрана."},"find":{"title":"Поиск на странице и масштаб","summary":"Найдите слова на текущей странице.","step":"Введите фразу и переходите между совпадениями.","recovery":"Скрытый или динамически загружаемый текст может появиться только после того, как страница его загрузит."},"keyboard":{"title":"Клавиатура для контроллера v2","summary":"Вводите текст с помощью контроллера.","step":"Переведите фокус в нужное поле, выберите символы и подтвердите ввод.","recovery":"Если символа нет, проверьте текущую раскладку клавиатуры."}}});
